import sys
from openpyxl import load_workbook

path = "budget.xlsx"
try:
    wb = load_workbook(path, data_only=False)
except FileNotFoundError:
    print("ERROR: budget.xlsx not found")
    sys.exit(1)

print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} (dims: {ws.dimensions}, max_row={ws.max_row}, max_col={ws.max_column}) ===")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 60)):
        vals = []
        for c in row:
            if c.value is not None:
                vals.append(f"{c.coordinate}={c.value!r}")
        if vals:
            print(" | ".join(vals))

